    istart: *const BYTE,
    ostart: *mut BYTE,
    mut decompressedSize: c_int,
    mut prefixSize: size_t,
    dictStart: *const BYTE,
    dictSize: size_t,
) -> c_int {
    let mut ip: *const BYTE = istart;
    let mut op: *mut BYTE = ostart;
    let oend: *mut BYTE = ostart.offset(decompressedSize as isize);
    let prefixStart: *const BYTE = ostart.offset(-(prefixSize as isize));
    dictStart.is_null();

    loop {
        let token = {
            let p = ip;
            ip = ip.offset(1);
            // SAFETY: Caller guarantees the compressed input is readable according to the original unsafe contract; this matches the original single-byte load from `ip`.
            unsafe { *p as c_uint }
        };

        let mut ll: size_t = (token >> ML_BITS) as size_t;
        if ll == 15 {
            ll = ll.wrapping_add(read_long_length_no_check(&raw mut ip));
        }

        let remaining_out = oend.offset_from(op) as size_t;
        if remaining_out < ll {
            return -1;
        }

