        unsafe {
            ::libc::memmove(op as *mut c_void, ip as *const c_void, ll as ::libc::size_t);
        }
        op = op.offset(ll as isize);
        ip = ip.offset(ll as isize);

        let remaining_out = oend.offset_from(op) as size_t;
        if remaining_out < MFLIMIT as size_t {
            if op == oend {
                break;
            }
            return -1;
        }

        let mut ml: size_t = (token & 15) as size_t;
        let offset: size_t = LZ4_readLE16(ip as *const c_void) as size_t;
        ip = ip.offset(2);

        if ml == 15 {
            ml = ml.wrapping_add(read_long_length_no_check(&raw mut ip));
        }
        ml = ml.wrapping_add(MINMATCH as size_t);

        let remaining_out = oend.offset_from(op) as size_t;
        if remaining_out < ml {
            return -1;
        }

        let prefix_avail = op.offset_from(prefixStart) as size_t;
        if offset > prefix_avail.wrapping_add(dictSize) {
            return -1;
        }

        let mut match_0: *const BYTE = op.offset(-(offset as isize));

        if offset > prefix_avail {
            let dictEnd: *const BYTE = dictStart.offset(dictSize as isize);
            let ext_offset = offset.wrapping_sub(prefix_avail);
            let extMatch: *const BYTE = dictEnd.offset(-(ext_offset as isize));
            let extml: size_t = dictEnd.offset_from(extMatch) as size_t;

            if extml > ml {
                // SAFETY: Source lies within the dictionary range and destination within output; overlap handling matches original memmove semantics.
                unsafe {
                    ::libc::memmove(op as *mut c_void, extMatch as *const c_void, ml as ::libc::size_t);
                }
                op = op.offset(ml as isize);
                ml = 0;
            } else {
                // SAFETY: Source lies within the dictionary range and destination within output; overlap handling matches original memmove semantics.
                unsafe {
                    ::libc::memmove(op as *mut c_void, extMatch as *const c_void, extml as ::libc::size_t);
                }
                op = op.offset(extml as isize);
                ml = ml.wrapping_sub(extml);
            }
            match_0 = prefixStart;
        }

        if ml != 0 {
            // SAFETY: The bytewise match copy in the original permits overlap; `ptr::copy` preserves memmove-like behavior for overlapping regions with identical bounds.
            unsafe {
                core::ptr::copy(match_0, op, ml);
            }
            op = op.offset(ml as isize);
        }

        let remaining_out = oend.offset_from(op) as size_t;
        if remaining_out < LASTLITERALS as size_t {
            return -1;
        }
    }

    ip.offset_from(istart) as c_int
